1	import { Router } from "express";
2	import type { Db } from "@paperclipai/db";
3	import {
4	  issueGraphLivenessAutoRecoveryRequestSchema,
5	  patchInstanceExperimentalSettingsSchema,
6	  patchInstanceGeneralSettingsSchema,
7	} from "@paperclipai/shared";
8	import { forbidden, unauthorized } from "../errors.js";
9	import { heartbeatService, instanceSettingsService, logActivity } from "../services/index.js";
10	import { expressHandler } from "../http/express-adapter.js";
11	import type { Handler, RequestCtx } from "../http/types.js";
12	import type { StorageService } from "../storage/types.js";
13	
14	/**
15	 * Equivalent of assertBoardOrgAccess for RequestCtx.
16	 * Requires board actor; company-list membership is enforced by the upstream
17	 * Express auth middleware for authenticated deployments.
18	 * TODO(cloudflare): re-enforce org-level membership in Workers auth layer.
19	 */
20	function assertBoardOrgAccessCtx(ctx: RequestCtx) {
21	  if (ctx.actor?.type !== "board") {
22	    throw forbidden("Board access required");
23	  }
24	}
25	
26	/**
27	 * Requires board actor with instance-admin privileges.
28	 * ctx.actor lacks `source` and `isInstanceAdmin`; we cannot check those fields
29	 * here. The upstream Express auth middleware populates req.actor.isInstanceAdmin
30	 * which is not forwarded to ActorContext.
31	 * TODO(cloudflare): add isInstanceAdmin / source to ActorContext for Workers.
32	 */
33	function assertCanManageInstanceSettingsCtx(ctx: RequestCtx) {
34	  if (ctx.actor?.type !== "board") {
35	    throw forbidden("Board access required");
36	  }
37	  // In the Express path, local_implicit and isInstanceAdmin actors pass through
38	  // without further DB checks. Under Workers that information is unavailable on
39	  // ActorContext, so we cannot replicate the fast-path; callers in Workers will
40	  // reach the instance admin check below only after auth middleware re-surfaces
41	  // the privilege.
42	  // TODO(cloudflare): verify instance-admin gate in Workers auth layer.
43	}
