45	function buildHandlers(db: Db) {
46	  const svc = instanceSettingsService(db);
47	  const heartbeat = heartbeatService(db);
48	
49	  // server/src/routes/instance-settings.ts:28
50	  const getGeneralSettings: Handler = async (ctx) => {
51	    assertBoardOrgAccessCtx(ctx);
52	    return Response.json(await svc.getGeneral());
53	  };
54	
55	  // server/src/routes/instance-settings.ts:35
56	  const patchGeneralSettings: Handler = async (ctx) => {
57	    assertCanManageInstanceSettingsCtx(ctx);
58	    const body = await ctx.json();
59	    const patch = patchInstanceGeneralSettingsSchema.parse(body);
60	    const updated = await svc.updateGeneral(patch);
61	
62	    // ctx.actor lacks `runId`; log with null runId.
63	    // TODO(cloudflare): thread runId through ActorContext.
64	    const actorType = ctx.actor!.type === "agent" ? "agent" as const : "user" as const;
65	    const actorId = ctx.actor!.type === "agent"
66	      ? (ctx.actor!.agentId ?? "unknown-agent")
67	      : (ctx.actor!.userId ?? "board");
68	    const companyIds = await svc.listCompanyIds();
69	    await Promise.all(
70	      companyIds.map((companyId) =>
71	        logActivity(db, {
72	          companyId,
73	          actorType,
74	          actorId,
75	          agentId: ctx.actor!.type === "agent" ? (ctx.actor!.agentId ?? null) : null,
76	          runId: null,
77	          action: "instance.settings.general_updated",
78	          entityType: "instance_settings",
79	          entityId: updated.id,
80	          details: {
81	            general: updated.general,
82	            changedKeys: Object.keys(patch).sort(),
83	          },
84	        }),
85	      ),
86	    );
87	    return Response.json(updated.general);
88	  };
89	
90	  // server/src/routes/instance-settings.ts:65
91	  const getExperimentalSettings: Handler = async (ctx) => {
92	    assertBoardOrgAccessCtx(ctx);
93	    return Response.json(await svc.getExperimental());
94	  };
95	
96	  // server/src/routes/instance-settings.ts:72
97	  const patchExperimentalSettings: Handler = async (ctx) => {
98	    assertCanManageInstanceSettingsCtx(ctx);
99	    const body = await ctx.json();
100	    const patch = patchInstanceExperimentalSettingsSchema.parse(body);
101	    const updated = await svc.updateExperimental(patch);
102	
103	    const actorType = ctx.actor!.type === "agent" ? "agent" as const : "user" as const;
104	    const actorId = ctx.actor!.type === "agent"
105	      ? (ctx.actor!.agentId ?? "unknown-agent")
106	      : (ctx.actor!.userId ?? "board");
107	    const companyIds = await svc.listCompanyIds();
108	    await Promise.all(
109	      companyIds.map((companyId) =>
110	        logActivity(db, {
111	          companyId,
112	          actorType,
113	          actorId,
114	          agentId: ctx.actor!.type === "agent" ? (ctx.actor!.agentId ?? null) : null,
115	          runId: null,
116	          action: "instance.settings.experimental_updated",
117	          entityType: "instance_settings",
118	          entityId: updated.id,
119	          details: {
120	            experimental: updated.experimental,
121	            changedKeys: Object.keys(patch).sort(),
122	          },
123	        }),
124	      ),
125	    );
126	    return Response.json(updated.experimental);
127	  };
128	
129	  // server/src/routes/instance-settings.ts:103
130	  const previewIssueGraphLivenessAutoRecovery: Handler = async (ctx) => {
131	    assertCanManageInstanceSettingsCtx(ctx);
132	    const body = await ctx.json();
133	    const parsed = issueGraphLivenessAutoRecoveryRequestSchema.parse(body);
134	    return Response.json(await heartbeat.buildIssueGraphLivenessAutoRecoveryPreview({
135	      lookbackHours: parsed.lookbackHours,
136	    }));
137	  };
138	
139	  // server/src/routes/instance-settings.ts:113
140	  const runIssueGraphLivenessAutoRecovery: Handler = async (ctx) => {
141	    assertCanManageInstanceSettingsCtx(ctx);
142	    const body = await ctx.json();
143	    const parsed = issueGraphLivenessAutoRecoveryRequestSchema.parse(body);
144	
145	    const actorType = ctx.actor!.type === "agent" ? "agent" as const : "user" as const;
146	    const actorId = ctx.actor!.type === "agent"
147	      ? (ctx.actor!.agentId ?? "unknown-agent")
148	      : (ctx.actor!.userId ?? "board");
149	    const result = await heartbeat.reconcileIssueGraphLiveness({
150	      runId: null,
151	      force: true,
152	      lookbackHours: parsed.lookbackHours,
153	    });
154	    const companyIds = await svc.listCompanyIds();
155	    await Promise.all(
156	      companyIds.map((companyId) =>
157	        logActivity(db, {
158	          companyId,
159	          actorType,
160	          actorId,
161	          agentId: ctx.actor!.type === "agent" ? (ctx.actor!.agentId ?? null) : null,
162	          runId: null,
163	          action: "instance.settings.issue_graph_liveness_auto_recovery_run",
164	          entityType: "instance_settings",
165	          entityId: "default",
166	          details: {
167	            lookbackHours: result.lookbackHours,
168	            escalationsCreated: result.escalationsCreated,
169	            existingEscalations: result.existingEscalations,
170	            skippedOutsideLookback: result.skippedOutsideLookback,
171	            escalationIssueIds: result.escalationIssueIds,
172	          },
173	        }),
174	      ),
175	    );
176	    return Response.json(result);
177	  };
178	
179	  return {
180	    getGeneralSettings,
181	    patchGeneralSettings,
182	    getExperimentalSettings,
183	    patchExperimentalSettings,
184	    previewIssueGraphLivenessAutoRecovery,
185	    runIssueGraphLivenessAutoRecovery,
186	  };
187	}
