189	export function instanceSettingsRoutes(db: Db) {
190	  const router = Router();
191	  const {
192	    getGeneralSettings,
193	    patchGeneralSettings,
194	    getExperimentalSettings,
195	    patchExperimentalSettings,
196	    previewIssueGraphLivenessAutoRecovery,
197	    runIssueGraphLivenessAutoRecovery,
198	  } = buildHandlers(db);
199	
200	  const storageSentinel = new Proxy({} as StorageService, {
201	    get(_target, prop) {
202	      throw new Error(`instanceSettings handler unexpectedly accessed storage.${String(prop)}`);
203	    },
204	  });
205	  const deps = { db, storage: storageSentinel };
206	
207	  router.get("/instance/settings/general", expressHandler(getGeneralSettings, deps));
208	  router.patch("/instance/settings/general", expressHandler(patchGeneralSettings, deps));
209	  router.get("/instance/settings/experimental", expressHandler(getExperimentalSettings, deps));
210	  router.patch("/instance/settings/experimental", expressHandler(patchExperimentalSettings, deps));
211	  router.post(
212	    "/instance/settings/experimental/issue-graph-liveness-auto-recovery/preview",
213	    expressHandler(previewIssueGraphLivenessAutoRecovery, deps),
214	  );
215	  router.post(
216	    "/instance/settings/experimental/issue-graph-liveness-auto-recovery/run",
217	    expressHandler(runIssueGraphLivenessAutoRecovery, deps),
218	  );
219	
220	  return router;
221	}
